const User = z.object({ id: z.uuid(), name: z.string().trim().min(1) });
type User = z.infer<typeof User>;       // output type
type UserInput = z.input<typeof User>;  // pre-transform input
const result = User.safeParse(payload);
if (!result.success) return result.error.flatten();

const Config = z.strictObject({
  port: z.coerce.number().int().min(1).max(65535),
  mode: z.enum(['dev', 'prod']),
  debug: z.boolean().default(false),
});

const Event = z.discriminatedUnion('type', [
  z.object({ type: z.literal('created'), id: z.uuid() }),
  z.object({ type: z.literal('deleted'), id: z.uuid(), reason: z.string() }),
]);

const Range = z.object({ start: z.date(), end: z.date() }).superRefine((value, ctx) => {
  if (value.end <= value.start) ctx.addIssue({ code: 'custom', path: ['end'], message: 'must follow start' });
});
const Slug = z.string().trim().toLowerCase().transform(s => s.replace(/\s+/g, '-'));

type Category = { name: string; children: Category[] };
const CategorySchema: z.ZodType<Category> = z.object({
  name: z.string(),
  get children() { return z.array(CategorySchema); },
});
const UserId = z.uuid().brand<'UserId'>();

const result = Schema.safeParse(input);
if (!result.success) {
  const tree = z.treeifyError(result.error);
  return { code: 'INVALID_INPUT', fields: tree.properties };
}
